__NUXT_JSONP__("/sp/feature", (function(a){return {data:[{details:{slug:"sp",pageTitle:"5 Razones por las que la gente elige MLI | Mentor Language Institute",pageDescription:"Hemos ayudado a más de 17,000 estudiantes a mejorar sus habilidades de inglés desde nuestra apertura.",section1:{title:"5 Razones por las que la gente elige MLI",image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fmli-mentor.jpg"},section2:{title:"5 Características de Mentor Language Institute",description:["Hemos ayudado a más de 17,000 estudiantes a mejorar sus habilidades de inglés desde nuestra apertura. ¿Por qué los estudiantes eligen MLI a pesar de que hay tantas escuelas de inglés en Los Ángeles? Tomamos una encuesta a estudiantes de MLI y sus respuestas están a continuación."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fsurvey.jpg",notes:"Periodo de encuesta: Enero a Junio del 2017 de 342 estudiantes"},section3:[{title:"No.1 : Precio Razonable",subtitle:"¡Gran precio! Desde $209 por semana. ¡Las clases de la tarde tienen un 40% de descuento en comparación con las clases de la mañana!",description:["La razón número 1 por la cual los estudiantes eligen MLI es la accesibilidad.","Cuanto más tiempo asistes a nuestra escuela, más barata es el curso. Si aplicas por 1 mes, la matrícula es de $ 1,220 o  \u003Cb\u003E$305 por semana\u003C\u002Fb\u003E. (¡este precio ya es excelente!) pero si solicitas 1 año (48 semanas), el curso es de $10,032 o  \u003Cspan style=\"color: #ff0000; font-weight: bold;\"\u003E$209 por semana\u003C\u002Fspan\u003E. Por favor, compare nuestras tarifas con otras escuelas."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002FPRICE_CHART_WEB_JAN06.jpg",links:[{icon:a,text:"más información sobre precios",link:"\u002Fsp\u002Fprice"}]},{title:"No.2 : Excelente ubicación",subtitle:"Westwood y Hollywood: Áreas populares de Los Ángeles",description:["Estamos ubicados en las mejores zonas de Los Ángeles, Westwood y Hollywood. Los estudiantes pueden acceder fácilmente a lugares famosos como Santa Monica y el centro de Los Ángeles."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fgreat-location.jpg",locations:[{image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fwestwood-campus.jpg",label:"Westwood Campus"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fhollywood-campus.jpg",label:"Hollywood Campus"}],links:[{icon:a,text:"Más información sobre el Campus de Westwood",link:"\u002Fsp\u002Fwestwood"},{icon:a,text:"Más información sobre el Campus de Hollywood",link:"\u002Fsp\u002Fhollywood"}]},{title:"No.3: Variedad de cursos de preparación universitaria",subtitle:"Muchos estudiantes se transfieren a UCLA ó Santa Monica College después de haber estudiado en MLI",description:["Ofrecemos cursos de preparación a exámenes populares como TOEFL, IELTS. Muchos estudiantes se transfieren a UCLA ó Santa Monica College después de haber estudiado en MLI"],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fgoing-to-college.jpg",links:[{icon:a,text:"Más información sobre cómo ir a un College",link:"\u002Fsp\u002Fgoing-to-college"}]},{title:"No.4 : Horarios de clase flexibles",subtitle:"Ofrecemos clases por la mañana, tarde y noche.",description:["MLI ofrece 3 horarios de clase distintos:Los estudiantes pueden elegir clases por la mañana, tarde y noche."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fclass-schedule.png",notes:"※Este horario de clase es para el Campus de Westwood. Si te gustaría saber los horarios del Campus de Hollywood, por favor contáctanos."},{title:"No.5 : Dormitorios",subtitle:"Ofrecemos la oportunidad de que te comuniques con estudiantes de todo el mundo en nuestros dormitorios.",description:["Organizamos no solo programas de alojamiento en casas de familia, sino también en dormitorios. Contamos con más de 40 habitaciones en el área de Los Ángeles y los dormitorios están ubicados cerca de cada campus. Muchos estudiantes se quedan en los dormitorios si es su primera vez en los Estados Unidos."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fdormitory.jpg",links:[{icon:a,text:"Más información sobre housing",link:"\u002Fsp\u002Fstay"}]}],dir:"\u002Ffeature",path:"\u002Ffeature\u002Fsp",extension:".json",createdAt:"2026-10-22T16:31:29.230Z",updatedAt:"2026-03-24T13:34:16.447Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));